from taf.gnb.oam.coam.vdu.services.trs.trs_v2 import TRSv2
from taf.gnb.oam.coam.vdu.releases.vduoam22r2 import vDuOAM22R2
from taf.gnb.oam.coam.vdu.schemas.trs_v2.certificates_info_v2 import CertificatesInfoTRSV2
from taf.gnb.oam.coam.vdu.schemas.trs_v2.CRLInformation_v2 import CRLInformationsTRSV2
from taf.gnb.oam.coam.vdu.schemas.asm.copy_managed_objects_response_v1 import CopyManagedObjectsResponseV1
from taf.gnb.oam.coam.vdu.schemas.asm.account_users_system_v1 import AccountUsersSystemAsmV1


class vDuOAM22R4(vDuOAM22R2):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM22R4, self).__init__(con_details, need_all_info)
        self.trs_v2 = TRSv2(con_details=con_details)

    def generate_vdu_csr(self, timeout=30, key_pool_type='RSA'):
        return self.trs_v2.generate_vdu_csr(timeout=timeout, key_pool_type=key_pool_type)

    def get_vdu_csr(self, timeout=30, key_pool_type='RSA'):
        return self.trs_v2.get_vdu_csr(timeout=timeout, key_pool_type=key_pool_type)

    def install_vdu_certificates(self, cert_file_path, cert_type='EE', cert_file_encoding='pem'):
        return self.trs_v2.install_vdu_certificates(cert_file_path, cert_type, cert_file_encoding)

    def get_vdu_certificates(self, timeout=30):
        certs = self.trs_v2.get_vdu_certificates(timeout=timeout)
        return list(map(CertificatesInfoTRSV2.from_object_dict, certs))

    def restore_default_certificates(self, timeout=30):
        return self.trs_v2.restore_default_certificates(timeout=timeout)

    def delete_certificates_by_id(self, id, timeout=30):
        return self.trs_v2.delete_certificates_by_id(id=id, timeout=30)

    def update_vdu_cmp_server_settings(self, ref_number, psk_key, timeout=30, key_pool_type='RSA'):
        return self.trs_v2.update_vdu_cmp_server_settings(ref_number=ref_number, psk_key=psk_key,
                                                          timeout=timeout, key_pool_type=key_pool_type)

    def get_vdu_crl_information(self, timeout=30):
        crls_info = self.trs_v2.get_vdu_crl_information(timeout=timeout)
        return CRLInformationsTRSV2.from_object_dict(crls_info)

    def initialize_certificate(self, timeout=30, key_pool_type='RSA'):
        return self.trs_v2.initialize_certificate(timeout=timeout, key_pool_type=key_pool_type)

    def update_cmp_server_key(self, timeout=30, key_pool_type='RSA'):
        return self.trs_v2.update_cmp_server_key(timeout=timeout, key_pool_type=key_pool_type)

    def update_CRL_info(self, timeout=30):
        return self.trs_v2.update_CRL_info(timeout=timeout)

    def update_vdu_psk_configuration(self, password, timeout=30):
        return self.trs.update_vdu_psk_configuration(password=password, timeout=timeout)

    def copy_managed_objects_into_delta_plan(self, plan_id, source_plan_id, parent_mo_uuid, mo_uuid, new_instance_id,
                                             include_children_objects, timeout=30):
        response = self.asm_v1.copy_managed_objects_into_delta_plan(plan_id=plan_id,
                                                                    parent_mo_uuid=parent_mo_uuid,
                                                                    source_plan_id=source_plan_id,
                                                                    mo_uuid=mo_uuid,
                                                                    new_instance_id=new_instance_id,
                                                                    include_children_objects=include_children_objects,
                                                                    timeout=timeout)

        return CopyManagedObjectsResponseV1.from_object_dict(response)

    def get_copy_managed_objects_into_delta_plan_status(self, plan_id, action_id, timeout=30):
        response = self.asm_v1.get_copy_managed_objects_into_delta_plan_status(plan_id=plan_id,
                                                                               action_id=action_id,
                                                                               timeout=timeout)
        return CopyManagedObjectsResponseV1.from_object_dict(response)

    def update_expired_password(self, new_password, curr_username='Nemuadmin', curr_password='nemuuser', timeout=30):
        res = self.asm_v1.update_expired_password(curr_password=curr_password,
                                                  new_password=new_password,
                                                  curr_username=curr_username,
                                                  timeout=timeout)
        return AccountUsersSystemAsmV1.from_object_dict(res)

    def get_ip_security_associations(self, policy_id, tnl_pod_hostname, timeout=30):
        return self.trs.get_ip_security_associations(policy_id=policy_id,
                                                     tnl_pod_hostname=tnl_pod_hostname,
                                                     timeout=timeout)
